{
  "name": "synagent-weixin-e2e",
  "private": true,
  "description": "End-to-end tests for the mini program, driven through WeChat DevTools",
  "scripts": { "test": "node run.js" },
  "dependencies": { "miniprogram-automator": "^0.13.0" }
}

const api = require('./lib/api');
const live = require('./lib/live');
const settings = require('./lib/settings');
const share = require('./lib/share');
const voice = require('./lib/voice');

App({
  onLaunch(options) {
    share.remember(options.query);
  },
  onShow(options) {
    share.remember(options.query);
    if (!api.getToken()) return;
    live.connect();
    api.suki.opened().catch(() => {});
    // Picks up their language. Until it arrives, the last one on this phone stays.
    settings.load().catch(() => {});
  },
  onHide() {
    live.disconnect();
    voice.stop();
  },
});

// The page's own behaviour: theme, sprites, cards, terminal steps. The 3D world is
// loaded separately and is optional; everything here works without it.

import { LANG, setLanguage, tr, translatePage } from './i18n.js';

const root = document.documentElement;
const THEME_KEY = 'synagent.theme';
const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;

/* ---------- Sprites: drawn as text, so they're crisp and follow the theme. ---------- */

