import { catalog } from './catalog';
import { chinaWording } from './catalog-cn';

// Copy is written in English and looked up by its English text, so a string with no translation
// just shows in English. Until someone chooses, the phone's language decides (deviceLanguage).
const COLUMN = { zh: 0, ko: 1, ja: 2, es: 3 } as const;
const LOCALE = { en: 'en', zh: 'zh-CN', ko: 'ko-KR', ja: 'ja-JP', es: 'es' } as const;

export type Language = keyof typeof LOCALE;

export const LANGUAGE_NAMES: readonly { value: Language; label: string }[] = [
  { value: 'en', label: 'English' },
  { value: 'zh', label: '中文' },
  { value: 'ko', label: '한국어' },
  { value: 'ja', label: '日本語' },
  { value: 'es', label: 'Español' },
];

let current: Language = 'en';

export const isLanguage = (v: unknown): v is Language => typeof v === 'string' && v in LOCALE;

/** The first of the device's preferred languages that we have, else English. */
export function deviceLanguage(): Language {
  const tags: string[] = [];
  const nav = (globalThis as { navigator?: { languages?: readonly string[]; language?: string } }).navigator;
  if (nav?.languages?.length) tags.push(...nav.languages);
  else if (nav?.language) tags.push(nav.language);
  try {
    tags.push(Intl.DateTimeFormat().resolvedOptions().locale);
  } catch {
    // No Intl: English.
  }
  for (const tag of tags) {
    const base = tag.toLowerCase().split(/[-_]/)[0];
    if (base !== 'en' && isLanguage(base)) return base;
    if (base === 'en') return 'en';
  }
  return 'en';
}

/** Copy is read as screens render, and the session re-renders them. Tables built at import time would stay in English. */
export function setLanguage(language: Language) {
  current = language;
}

export const currentLanguage = () => current;

/** For dates and times, so they match the words around them. */
export const dateLocale = () => LOCALE[current];

/** Served from the China copy (suki.zhiyuwujie.top), the app reads as finding company in every language. */
const inChina = (() => {
  const host = (globalThis as { location?: { hostname?: string } }).location?.hostname ?? '';
  return host === 'zhiyuwujie.top' || host.endsWith('.zhiyuwujie.top');
})();

export function tr(english: string, vars?: Record<string, string | number>) {
  const column = COLUMN[current as keyof typeof COLUMN];
  let text = column === undefined ? english : (catalog[english]?.[column] ?? english);
  const cn = inChina && current !== 'zh' ? chinaWording[english] : undefined;
  if (cn?.[current as keyof typeof cn]) text = cn[current as keyof typeof cn] as string;
  for (const [k, v] of Object.entries(vars ?? {})) text = text.replace(`{${k}}`, String(v));
  return text;
}

const i18n = require('../../../lib/i18n');
const settings = require('../../../lib/settings');
const { showError } = require('../../../lib/format');

const COPY = {
  loading: 'Getting your settings...',
  language: 'Language',
  languageHint: 'For the app and for Suki.',
  notifyAbout: 'Notify me about',
  matches: 'New introductions and matches',
  messages: 'Messages',
  dates: 'Dates',
  suki: 'Things Suki wants to tell me',
  email: 'Also by email',
  chats: 'Chats',
  receipts: 'Read receipts',
  receiptsHint: "People can see when you've read their message.",
  perDay: 'Introductions per day',
  perDayHint: 'The most Suki will bring you in one day. She may bring fewer.',
};

Page({
  data: { t: i18n.strings(COPY), s: null, languages: i18n.LANGUAGES, daily: [1, 2, 3, 4, 5] },
  onShow() {
    i18n.apply(this, COPY, 'App');
    this.load();
  },
  async load() {
    try {
      this.setData({ s: await settings.load() });
    } catch (e) {
      if (e.status !== 401) showError(e);
    }
  },
  // Shows the change right away, and goes back to what's saved if it doesn't save.
  async save(change) {
    this.setData({ s: Object.assign({}, this.data.s, change) });
    try {
      this.setData({ s: await settings.patch(change) });
    } catch (e) {
      this.setData({ s: settings.current() });
      showError(e);
    }
  },
  onToggle(e) {
    this.save({ [e.currentTarget.dataset.f]: e.detail.value });
  },
  onPick(e) {
    const { f, v } = e.currentTarget.dataset;
    if (this.data.s[f] !== v) this.save({ [f]: v });
  },
});
